#!/usr/bin/env node

import { spawnSync } from "node:child_process";
import { randomUUID } from "node:crypto";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { conformCanonicalBytes, conformTerm } from "@emsenn/rmn-semantic-conformance/client";
import { assayWitTransition } from "@emsenn/wit-transition-assay/client";
import { recordLocalRwil, relationalRwilDocument } from "@emsenn/rwil-rdf-services/client";
import { CONTRACT } from "./law.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");
const HARNESS = resolve(ROOT, "run-one-exchange.mjs");
export const ACTOR = "urn:ame:groq-inference-team";
export const ACCOUNT = JSON.parse(readFileSync(resolve(ROOT, "content/evm/accounts/eip155-31337.json"), "utf8")).account.caip10;
export const LAW = CONTRACT;
export const OPERATION_TYPE = ["product", ["mark"], ["product", ["mark"], ["product", ["mark"], ["mark"]]]];
const MODEL = "llama-3.1-8b-instant";
const RATE_POLICY = JSON.parse(readFileSync(join(ROOT, "content", "policies", "typed-inference-rate-capacity.json"), "utf8"));

export function runWithCapacityAdmission(executable, args, {
  lockPath = resolve(process.env.GROQ_CAPACITY_LOCK ?? join(ROOT, "data", "groq-request-slot.lock")),
  admissionTimeoutMs = Number(process.env.GROQ_INFERENCE_RATE_ADMISSION_TIMEOUT_MS ?? RATE_POLICY.admissionTimeoutMilliseconds),
  ...spawnOptions
} = {}) {
  if (!Number.isInteger(admissionTimeoutMs) || admissionTimeoutMs < 0 || admissionTimeoutMs > 300_000) throw new Error("GROQ_INFERENCE_RATE_ADMISSION_TIMEOUT_MS must be 0..300000");
  mkdirSync(dirname(lockPath), { recursive: true });
  return spawnSync("flock", ["--exclusive", "--no-fork", "--wait", String(admissionTimeoutMs / 1_000), lockPath, executable, ...args], spawnOptions);
}

function requiredAgent(name) { const value = process.env[name]; if (!value) throw new Error(`${name} must name the hired provider's A2A 1.0 Agent Card`); return value; }
function rawPart(message) { const parts = (message.parts ?? []).filter((part) => part?.mediaType === "application/rmn+cbor" && typeof part.raw === "string"); if (parts.length !== 1) throw new Error("Groq inference requires exactly one application/rmn+cbor A2A part"); return parts[0]; }
function operationMarks(term) {
  if (term?.[0] !== "pair" || term?.[1]?.[0] !== "mark" || term?.[2]?.[0] !== "pair" || term?.[2]?.[1]?.[0] !== "mark" || term?.[2]?.[2]?.[0] !== "pair" || term?.[2]?.[2]?.[1]?.[0] !== "mark" || term?.[2]?.[2]?.[2]?.[0] !== "mark") throw new Error("inference operation is not instruction/input/model/mode Marks");
  return { instruction: term[1][1], input: term[2][1][1], model: term[2][2][1][1], mode: term[2][2][2][1] };
}
function measures(prior, usage = {}) { const byDimension = new Map((prior ?? []).map((measure) => [measure.dimension, measure])); byDimension.set("provider-request", { dimension: "provider-request", quantity: "1", unit: "groq-api-request" }); if (Number.isInteger(usage.prompt_tokens)) byDimension.set("input-token", { dimension: "input-token", quantity: String(usage.prompt_tokens), unit: "token" }); if (Number.isInteger(usage.completion_tokens)) byDimension.set("output-token", { dimension: "output-token", quantity: String(usage.completion_tokens), unit: "token" }); return [...byDimension.values()]; }
async function appendRwil({ proposal, completion, evidence, witness, disposition }) { const at = new Date().toISOString(); const assertions = [["urn:rmn:proposal", proposal], ["urn:rmn:completion", completion], ["urn:rmn:evidence", evidence], ["urn:rmn:witness", witness], ["urn:rmn:disposition", disposition], ["urn:prov:generatedAtTime", at]].map(([predicate, value]) => ({ subject: completion, predicate, object: { kind: "literal", value } })); return recordLocalRwil({ agentUrl: requiredAgent("RWIL_RDF_AGENT"), root: resolve(process.env.GROQ_RWIL_ROOT ?? join(ROOT, "data")), nodeId: "groq-inference-team", batch: { settlement: ACCOUNT, graph: completion, recordedAt: at, document: relationalRwilDocument({ type: "InferenceExecutionWitness", proposal, completion, evidence, witness, disposition }), assertions } }); }
function perform({ instruction, input, model, mode }) {
  if (!["dry-run", "live"].includes(mode)) throw new Error("inference mode Mark must be dry-run or live");
  if (![instruction, input, model].every((part) => typeof part === "string" && part.length > 0)) throw new Error("instruction, input, and model Marks must be nonempty text");
  if (model !== MODEL) throw new Error(`Groq provider does not offer model ${model}`);
  const fuelMs = Number(process.env.GROQ_INFERENCE_EXCHANGE_FUEL_SECONDS ?? 120) * 1_000;
  const admissionMs = Number(process.env.GROQ_INFERENCE_RATE_ADMISSION_TIMEOUT_MS ?? RATE_POLICY.admissionTimeoutMilliseconds);
  const intervalMs = Number(process.env.GROQ_INFERENCE_MIN_INTERVAL_MS ?? RATE_POLICY.minimumLiveExchangeIntervalMilliseconds);
  if (!Number.isInteger(intervalMs) || intervalMs < 0 || intervalMs > 180_000) throw new Error("GROQ_INFERENCE_MIN_INTERVAL_MS must be 0..180000");
  const temp = mkdtempSync(join(tmpdir(), "groq-rmn-inference-")); const packet = join(temp, "packet.json");
  try {
    writeFileSync(packet, `${JSON.stringify({ model, messages: [{ role: "system", content: instruction }, { role: "user", content: input }] })}\n`, "utf8");
    const result = runWithCapacityAdmission(process.execPath, [HARNESS, packet, ...(mode === "dry-run" ? ["--dry-run"] : [])], { cwd: ROOT, env: { ...process.env, GROQ_INFERENCE_MIN_INTERVAL_MS: String(intervalMs) }, encoding: "utf8", admissionTimeoutMs: admissionMs, timeout: admissionMs + intervalMs + fuelMs + 10_000 });
    if (result.status !== 0) throw new Error(`Groq harness or request-slot admission refused before settlement: ${(result.stderr || result.error?.message || "no detail").trim().slice(0, 500)}`);
    const exchange = JSON.parse(result.stdout);
    if (mode === "dry-run") return { disposition: "completion", text: "ready", usage: {} };
    if (exchange.outcome === "refusal") return { disposition: "refused", text: exchange.refusal?.grounds ?? "Groq refused the exchange", usage: {} };
    if (typeof exchange.completion?.text !== "string" || exchange.completion.text.length === 0) throw new Error("Groq harness returned no text completion");
    return { disposition: "completion", text: exchange.completion.text, usage: exchange.completion.raw?.usage ?? {} };
  } finally { rmSync(temp, { recursive: true, force: true }); }
}

export async function executeMessage(message) {
  if (message?.role !== "ROLE_USER") throw new Error("contracted Groq executor requires an A2A ROLE_USER Message");
  const part = rawPart(message); const proposal = await conformCanonicalBytes({ agentUrl: requiredAgent("RMN_CONFORMANCE_AGENT"), bytes: Buffer.from(part.raw, "base64"), expectedType: ["product", ["effect"], OPERATION_TYPE], expectedNi: part.metadata?.ni }); const cell = proposal.effectCell;
  if (cell.law !== LAW || cell.provider !== ACCOUNT) throw new Error("effect cell is not addressed to the Groq team's law, account, and task scale");
  if (cell.outcome?.positiveEvidence !== false || cell.outcome?.negativeEvidence !== false) throw new Error("proposal effect must enter at FOUR-bottom");
  const operation = proposal.normalForm[2]; let performed; try { performed = perform(operationMarks(operation)); } catch (error) { performed = { disposition: "refused", text: error.message, usage: {} }; }
  const evidence = await conformTerm({ agentUrl: requiredAgent("RMN_CONFORMANCE_AGENT"), term: ["mark", performed.text], expectedType: ["mark"] }); const completionCell = { ...cell, evidenceRoot: evidence.term, outcome: { positiveEvidence: performed.disposition === "completion", negativeEvidence: performed.disposition === "refused" }, measures: measures(cell.measures, performed.usage) };
  const transition = await assayWitTransition({ agentUrl: requiredAgent("WIT_TRANSITION_ASSAY_AGENT"), proposalCell: cell, completionCell, evidence: evidence.term }); const completion = await conformTerm({ agentUrl: requiredAgent("RMN_CONFORMANCE_AGENT"), term: ["pair", ["effect", completionCell], operation], expectedType: ["product", ["effect"], OPERATION_TYPE] });
  await appendRwil({ proposal: proposal.term, completion: completion.term, evidence: evidence.term, witness: transition.witness, disposition: performed.disposition });
  return { messageId: randomUUID(), role: "ROLE_AGENT", parts: [{ raw: completion.canonicalBytesBase64, metadata: { ni: completion.term }, filename: "completion.rmn.cbor", mediaType: "application/rmn+cbor" }, { text: performed.text, metadata: { evidenceNi: evidence.term, disposition: performed.disposition }, mediaType: "text/plain" }], metadata: { disposition: performed.disposition, proposalNi: proposal.term, completionNi: completion.term, witnessNi: transition.witness } };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) { try { process.stdout.write(`${JSON.stringify(await executeMessage(JSON.parse(readFileSync(0, "utf8"))))}\n`); } catch (error) { process.stderr.write(`${error.stack ?? error.message}\n`); process.exitCode = 1; } }


